        if(!$periodMode){
            $ledger=new BalanceLedger($db,$actor);$sources=new BalanceSources($db,$actor);$ledger->create(2025);$state=$ledger->report(2025);$bankId=array_key_first($sources->bankAccounts());$ledger->setup(2025,$state['version'],$state['accounts'],[['account'=>$bankId,'debit_cents'=>100000,'credit_cents'=>0,'sphere'=>''],['account'=>'equity','debit_cents'=>0,'credit_cents'=>100000,'sphere'=>'']],'equity','Own verified opening bank1000',true);
            foreach([['invoice',$entry,$opts],['transaction',$source,[]]] as [$type,$id,$input]){$preview=$sources->preview(2025,$type,$id,$input);$check(!$preview['issues'],'actual calendar '.$type.' source is fully reconciled: '.implode(' ',$preview['issues']));$ledger->importSource(2025,$ledger->report(2025)['version'],$type,$id,$input,$preview['hash'],true);}
